WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY event_type ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('MONTH', event_time) AS activity_month, MAX(event_time) AS last_seen, COUNT_IF(page = '/checkout') AS checkout_events, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list FROM sessionized GROUP BY DATE_TRUNC('MONTH', event_time) ORDER BY activity_month DESC NULLS LAST
